sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    var parentId;
    var childAggregated = new GlideRecord('x_hsb11_hsbcmss_eh_aggregated_trade_email_queue');
    childAggregated.addQuery('trade_case', current.sys_id);
    childAggregated.query();
    while (childAggregated.next()) {
        var childAggregatedRec = new GlideRecord('x_hsb11_hsbcmss_eh_aggregated_trade_email_queue');
        childAggregatedRec.addQuery('parent', childAggregated.parent.sys_id);
        childAggregatedRec.query();
        var countChild = childAggregatedRec.getRowCount();
        var countCheck = 0;
        while (childAggregatedRec.next()) {
            if (parentId) {
                parentId = parentId + ',' + childAggregatedRec.trade_case.sys_id;
            } else {
                parentId = childAggregatedRec.trade_case.sys_id;
            }
            if (childAggregatedRec.trade_case.state == 3 || childAggregatedRec.trade_case.state == 7) {
                countCheck = countCheck + 1;
            }
        }
        if (countCheck == countChild) {
            var emailCase = new GlideRecord('x_hsb11_hsbcmss_eh_hsbc_email_case');
            //emailCase.addQuery('trade_case_number', current.sys_id);
            emailCase.addEncodedQuery('trade_case_number.sys_idIN' + parentId);
            emailCase.addEncodedQuery('stateNOT IN3,7');
            emailCase.query();
            while (emailCase.next()) {
                if (current.state == 3) //Closed complete
                {
                    emailCase.setValue('state', 3);
                } else if (current.state == 7) {
                    emailCase.setValue('state', 7); //Cancelled
                    emailCase.setValue('active', false);

                }
                emailCase.update();
            }

        }

		// MSSRBXCE-509, Updating actioned fieald on child Aggregate as per the trade case state is Canelled or Close complete
        var childRecord = new GlideRecord('x_hsb11_hsbcmss_eh_aggregated_trade_email_queue');
        childRecord.addEncodedQuery('trade_case.state=3^ORtrade_case.state=7^trade_case=' + current.sys_id);
        childRecord.query();
        while (childRecord.next()) {
            childRecord.setValue('actioned', true);
            childRecord.update();
        }

    }
})(current, previous);
